// Obtém todas as transações retornadas pela API REST
const inputItems = $input.all();

// Converte a lista de itens da entrada em um array simples de objetos JSON
const transacoes = inputItems.map(item => item.json);

// 1. Filtrar apenas transações com status "APPROVED"
const transacoesAprovadas = transacoes.filter(t => t.status === 'APPROVED');

// 2. Cálculos Globais
const totalTransacoes = transacoes.length;
const qtdAprovadas = transacoesAprovadas.length;

// Soma o total faturado das vendas aprovadas
const totalFaturado = transacoesAprovadas.reduce((acc, t) => acc + (Number(t.valor) || 0), 0);

// Média de valor por venda aprovada (Tíquete Médio)
const tiqueteMedio = qtdAprovadas > 0 ? (totalFaturado / qtdAprovadas) : 0;

// Taxa de Aprovação em porcentagem
const taxaAprovacao = totalTransacoes > 0 ? ((qtdAprovadas / totalTransacoes) * 100) : 0;

// Data de referência (ontem no formato YYYY-MM-DD)
const ontem = new Date();
ontem.setDate(ontem.getDate() - 1);
const dataRelatorio = ontem.toISOString().split('T')[0];

// 3. Formatação e Estruturação do Payload Limpo
const relatorio = {
  data_relatorio: dataRelatorio,
  total_faturado: totalFaturado,
  total_faturado_formatado: `R$ ${totalFaturado.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`,
  qtd_total_transacoes: totalTransacoes,
  qtd_vendas_aprovadas: qtdAprovadas,
  tiquete_medio: Number(tiqueteMedio.toFixed(2)),
  tiquete_medio_formatado: `R$ ${tiqueteMedio.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`,
  taxa_aprovacao_pct: Number(taxaAprovacao.toFixed(2)),
  taxa_aprovacao_formatada: `${taxaAprovacao.toFixed(2)}%`,
  processado_em: new Date().toISOString()
};

return [{ json: relatorio }];
